SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE hoan_tien;
TRUNCATE TABLE giao_dich;
-- TRUNCATE TABLE don_hang_km; /* Bỏ comment nếu bảng này tồn tại */
TRUNCATE TABLE chi_tiet_don_hang;
TRUNCATE TABLE don_hang;
TRUNCATE TABLE ton_kho;
TRUNCATE TABLE dia_chi;
DELETE FROM tai_khoan WHERE vai_tro = 'khach_hang' AND ten_dang_nhap LIKE 'khach%';
SET FOREIGN_KEY_CHECKS = 1;

/* --- INSERT DỮ LIỆU --- */

/* --- UPDATE TỔNG HỢP SỐ LIỆU --- */

UPDATE san_pham sp
LEFT JOIN (
    SELECT ctdh.ma_san_pham, SUM(ctdh.so_luong) AS total_sold
    FROM chi_tiet_don_hang ctdh
    JOIN don_hang dh ON ctdh.ma_don_hang = dh.id
    WHERE dh.trang_thai = 'da_giao'
    GROUP BY ctdh.ma_san_pham
) x ON sp.id = x.ma_san_pham
SET sp.so_luong_ban = COALESCE(x.total_sold, 0);


UPDATE san_pham sp
JOIN ton_kho tk ON sp.id = tk.ma_san_pham
SET sp.so_luong_ton = tk.so_luong;
